  <script>
    // Simple inline 2-minute cue when pressing the inline try button
    (function(){
      const btn = document.getElementById('try-inline');
      btn.addEventListener('click',()=>{
        const start = Date.now(); const total=120000; btn.disabled=true; const orig=btn.textContent;
        const id = setInterval(()=>{
          const rem = Math.max(0, total - (Date.now()-start));
          const s = Math.ceil(rem/1000);
          btn.textContent = 'Breath cue — '+s+"s";
          if(rem<=0){ clearInterval(id); btn.textContent=orig; btn.disabled=false; alert('Nice — a short reset. Try it again when you need a pause.'); }
        },250);
        // gentle audio-free guidance via aria-live
        const live = document.createElement('div'); live.setAttribute('aria-live','polite'); live.className='sr-only'; live.textContent='Start with a slow inhale. Then exhale for longer.'; document.body.appendChild(live);
        setTimeout(()=>live.remove(),4000);
      });
    })();

    // Reveal logic with prefers-reduced-motion
    (function(){
      const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const items = document.querySelectorAll('[data-reveal]');
      if(reduced){ items.forEach(i=>i.classList.add('visible')); return }
      const observer = new IntersectionObserver((entries)=>{ entries.forEach(e=>{ if(e.isIntersecting){ e.target.classList.add('visible'); observer.unobserve(e.target); } }) },{threshold:0.1});
      items.forEach(i=>observer.observe(i));
    })();
  </script>
